    private final String flagId;      // stable id for idempotency
    private final String accountId;
    private final BigDecimal amount;
    private final boolean poison;     // simulate a record that fails processing

    FraudFlag(String flagId, String accountId, BigDecimal amount, boolean poison) {
        this.flagId = flagId;
        this.accountId = accountId;
        this.amount = amount;
        this.poison = poison;
    }

    String getFlagId() { return flagId; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    boolean isPoison() { return poison; }
