package com.bank.kda.lambda;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

// The Lambda function: idempotent per-flag actions (enrich, decide, act).
class LambdaHandler {
    private static final Logger log = Logger.getLogger(LambdaHandler.class.getName());

    // Idempotency store: flag ids already acted on (would be DynamoDB in AWS).
    private final Set<String> processed = new HashSet<>();
    private final List<FraudFlag> deadLetter = new ArrayList<>();

    // Process a batch; return ids that failed (to be retried / dead-lettered).
    List<FraudFlag> handleBatch(List<FraudFlag> batch) {
        List<FraudFlag> failures = new ArrayList<>();
        for (FraudFlag f : batch) {
            if (processed.contains(f.getFlagId())) {
                log.info(() -> "idempotent skip (already acted) " + f.getFlagId());
                continue;
            }
            try {
                act(f);                     // may throw for poison records
                processed.add(f.getFlagId());
            } catch (RuntimeException ex) {
                log.severe(() -> "processing failed for " + f.getFlagId() + ": " + ex.getMessage());
                failures.add(f);
            }
        }
        return failures;
    }

    // The custom action: enrich, decide, and act (SNS/freeze/DynamoDB).
    private void act(FraudFlag f) {
        if (f.isPoison()) throw new RuntimeException("enrichment API error");
        String contact = lookupContact(f.getAccountId());     // enrich
        boolean freeze = f.getAmount().doubleValue() > 500000; // decide
        log.info(() -> "ACTION flag=" + f.getFlagId() + " account=" + f.getAccountId()
                + " freezeCard=" + freeze + " notify=" + contact);
    }

    private String lookupContact(String accountId) {
        return accountId + "@sms"; // stand-in for external enrichment
    }

    void deadLetter(FraudFlag f) {
        deadLetter.add(f);
        log.warning(() -> "DEAD-LETTER " + f.getFlagId());
    }

    List<FraudFlag> getDeadLetter() { return deadLetter; }
}
