package com.bank.kda.lambda;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Batches analytics output and invokes the Lambda handler with retries,
// routing permanently-failing records to the dead-letter destination.
class EventSourceMapping {
    private static final Logger log = Logger.getLogger(EventSourceMapping.class.getName());
    private final int batchSize;
    private final int maxRetries;
    private final LambdaHandler handler;

    EventSourceMapping(int batchSize, int maxRetries, LambdaHandler handler) {
        this.batchSize = batchSize;
        this.maxRetries = maxRetries;
        this.handler = handler;
    }

    void deliver(List<FraudFlag> outputStream) {
        List<FraudFlag> batch = new ArrayList<>();
        for (FraudFlag f : outputStream) {
            batch.add(f);
            if (batch.size() == batchSize) { invokeWithRetry(batch); batch = new ArrayList<>(); }
        }
        if (!batch.isEmpty()) invokeWithRetry(batch);
    }

    private void invokeWithRetry(List<FraudFlag> batch) {
        log.info(() -> "invoke Lambda with batch of " + batch.size());
        List<FraudFlag> remaining = batch;
        for (int attempt = 1; attempt <= maxRetries + 1 && !remaining.isEmpty(); attempt++) {
            int a = attempt;
            log.fine(() -> "attempt " + a);
            remaining = handler.handleBatch(remaining);
        }
        // Still failing after retries -> dead-letter.
        for (FraudFlag f : remaining) handler.deadLetter(f);
    }
}
