package com.bank.kda.lambda;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LambdaIntegrationDemo {
    private static final Logger log = Logger.getLogger(LambdaIntegrationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        LambdaHandler lambda = new LambdaHandler();
        EventSourceMapping mapping = new EventSourceMapping(3, 3, lambda);

        // Analytics output stream of flags: includes a duplicate and a poison record.
        List<FraudFlag> output = List.of(
            new FraudFlag("F1", "SAV2001", new BigDecimal("900000"), false), // freeze
            new FraudFlag("F2", "CUR3001", new BigDecimal("12000"), false),
            new FraudFlag("F1", "SAV2001", new BigDecimal("900000"), false), // duplicate
            new FraudFlag("F3", "SAV2002", new BigDecimal("600000"), true),  // poison -> DLQ
            new FraudFlag("F4", "CUR3002", new BigDecimal("40000"), false)
        );

        mapping.deliver(output);
        log.info("dead-letter count = " + lambda.getDeadLetter().size());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
